INSERT INTO `categories` (`id`, `slug`, `name_ar`, `name_en`, `description_ar`, `description_en`, `icon`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (1, 'social-media', 'خدمات السوشل ميديا', 'Social Media Services', 'متابعين، لايكات، مشاهدات وترويج لإنستغرام وتيك توك وفيسبوك وتلكرام.', 'Followers, likes, views and promotion for Instagram, TikTok, Facebook and Telegram.', 'users', 10, 1, '2026-10-28 11:50:43.959', '2026-10-28 11:50:46.527');
INSERT INTO `categories` (`id`, `slug`, `name_ar`, `name_en`, `description_ar`, `description_en`, `icon`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (2, 'gaming', 'شحن الألعاب', 'Game Top-ups', 'شدات ببجي، ألماس موبايل ليجندز، وألماس وذهب لودو ستار برقم اللاعب فقط — خلال 10 إلى 20 دقيقة من تأكيد الدفع.', 'PUBG UC, Mobile Legends diamonds and Ludo Star diamonds and gold with your player ID only — within 10–20 minutes of payment confirmation.', 'gamepad', 20, 1, '2026-10-28 11:50:43.959', '2026-10-28 11:50:46.706');
