INSERT INTO `categories` (`id`, `slug`, `name_ar`, `name_en`, `description_ar`, `description_en`, `icon`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (12, 'balance-exchange', 'تبديل الرصيد', 'Balance Exchange', 'تبديل بين آسياسيل وزين كاش وكي كارد بكل الاتجاهات. اطلب الخدمة واكتب المبلغ والاتجاه، ونرد عليك بالسعر.', 'Exchange between AsiaCell, Zain Cash and Qi Card in any direction. Request it with the amount and direction and we reply with the rate.', 'card', 55, 1, '2026-10-28 11:50:46.523', '2026-10-28 11:50:46.706');
INSERT INTO `categories` (`id`, `slug`, `name_ar`, `name_en`, `description_ar`, `description_en`, `icon`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (14, 'gift-cards', 'بطاقات الهدايا', 'Gift Cards', 'بطاقات بلايستيشن وستيم وجوجل بلاي وآب ستور وإكس بوكس للحساب الأمريكي. الدفع أولاً ثم استلام الكود.', 'PlayStation, Steam, Google Play, App Store and Xbox cards for US accounts. Pay first, then receive the code.', 'gift', 25, 1, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.702');
