INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (15, 5, 'whatsapp-telegram-number', 'رقم لتفعيل واتساب أو تلكرام', 'Number for WhatsApp or Telegram activation', 'رقم واحد بـ 5,000 دينار لتفعيل حسابك الخاص.', '5,000 IQD per number to activate your own account.', 'رقم لتفعيل حساب واتساب أو تلكرام خاص بك. بعد تأكيد الدفع يرسل لك فريق الدعم الرقم ورمز التفعيل عبر المحادثة.\n\n- للاستخدام المشروع فقط ووفق شروط التطبيق والقوانين.\n- يُمنع استخدامه للاحتيال أو الإزعاج أو انتحال الشخصية، ويحق للمتجر رفض الطلب.\n- لا نطلب منك أي كلمة مرور.', 'A number to activate your own WhatsApp or Telegram account. After payment is confirmed, support sends you the number and the activation code in chat.\n\n- Lawful use only, in line with the app\'s terms and the law.\n- Not for fraud, spam or impersonation; the store may refuse any order.\n- We never ask for any password.', 'phone', NULL, 'unit', 5000, NULL, 1, 5, 'من 10 إلى 20 دقيقة بعد تأكيد الدفع', '10–20 minutes after payment is confirmed', 1, 0, 0, 5, '2026-10-28 11:50:46.299', '2026-10-28 11:50:46.827');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (16, 1, 'facebook-followers', 'متابعين فيسبوك', 'Facebook Followers', '1,000 متابع بـ 3,000 دينار فقط.', '1,000 followers for just 3,000 IQD.', 'اختر الباقة وأدخل رابط صفحتك أو حسابك العام على فيسبوك. يبدأ التنفيذ بعد تأكيد الدفع.\n\nلا نطلب كلمة المرور أبداً.', 'Choose a package and enter your public Facebook page or profile link. Work starts after payment is confirmed.\n\nWe never ask for your password.', 'users', NULL, 'package', NULL, NULL, 1, 10, 'يبدأ خلال 10 إلى 20 دقيقة من تأكيد الدفع ويكتمل خلال 48 ساعة كحد أقصى', 'Starts within 10–20 minutes of payment; completes within 48 hours at most', 1, 0, 0, 12, '2026-10-28 11:50:46.523', '2026-10-28 11:50:46.829');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (17, 1, 'social-promotion', 'ترويج ممول (إنستغرام / تيك توك / فيسبوك)', 'Paid Promotion (Instagram / TikTok / Facebook)', 'باقة البداية بـ 10,000 دينار، والحملات الأكبر حسب الطلب.', 'Starter package 10,000 IQD; bigger campaigns on request.', 'نروّج منشورك أو حسابك للجمهور اللي تختاره. باقة البداية بـ 10,000 دينار، وكل 10,000 إضافية تكبّر الحملة (الكمية = عدد الباقات).\n\nللحملات الخاصة اطلب «خدمة خاصة» ونرسل لك عرضاً.', 'We promote your post or account to the audience you choose. The starter package is 10,000 IQD; each extra 10,000 grows the campaign (quantity = number of packages).\n\nFor special campaigns, send a custom request and we will send an offer.', 'megaphone', NULL, 'unit', 10000, NULL, 1, 20, 'تبدأ الحملة خلال 24 ساعة', 'Campaign starts within 24 hours', 1, 0, 0, 30, '2026-10-28 11:50:46.523', '2026-10-28 11:50:46.523');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (18, 2, 'ludo-star-diamonds', 'لودو ستار — ألماس', 'Ludo Star — Diamonds', 'كل ما كبرت الباقة كان سعر الوحدة أرخص — شحن برقم اللاعب فقط.', 'The bigger the package, the cheaper each unit — top-up with your player ID only.', 'اختر الباقة وأدخل رقم اللاعب (ID) في لودو ستار. لا نطلب كلمة المرور أو تسجيل الدخول.', 'Choose a package and enter your Ludo Star player ID. We never ask for your password or login.', 'gem', NULL, 'package', NULL, NULL, 1, 10, 'من 10 إلى 20 دقيقة بعد تأكيد الدفع', '10–20 minutes after payment is confirmed', 1, 1, 0, 20, '2026-10-28 11:50:46.523', '2026-10-28 11:50:46.827');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (19, 2, 'ludo-star-gold', 'لودو ستار — ذهب', 'Ludo Star — Gold', 'كل ما كبرت الباقة كان سعر الوحدة أرخص — شحن برقم اللاعب فقط.', 'The bigger the package, the cheaper each unit — top-up with your player ID only.', 'اختر الباقة وأدخل رقم اللاعب (ID) في لودو ستار. لا نطلب كلمة المرور أو تسجيل الدخول.', 'Choose a package and enter your Ludo Star player ID. We never ask for your password or login.', 'spark', NULL, 'package', NULL, NULL, 1, 10, 'من 10 إلى 20 دقيقة بعد تأكيد الدفع', '10–20 minutes after payment is confirmed', 1, 0, 0, 21, '2026-10-28 11:50:46.523', '2026-10-28 11:50:46.827');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (20, 3, 'chatgpt-plus', 'اشتراك ChatGPT Plus', 'ChatGPT Plus Subscription', 'الاشتراك الاحترافي — 30,000 دينار.', 'The pro plan — 30,000 IQD.', 'اشتراك ChatGPT Plus بمميزات احترافية أعلى من اشتراك Go.\n\nيتم التفعيل بالتنسيق مع الدعم بعد تأكيد الدفع. لا نطلب كلمة المرور أو رمز التحقق أبداً.', 'ChatGPT Plus with more advanced features than the Go plan.\n\nActivation is arranged with support after payment is confirmed. We never ask for your password or verification code.', 'chat', NULL, 'package', NULL, NULL, 1, 3, 'من 10 دقائق إلى ساعة بعد تأكيد الدفع', '10 minutes to 1 hour after payment is confirmed', 1, 1, 0, 10, '2026-10-28 11:50:46.523', '2026-10-28 11:50:46.828');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (21, 3, 'chatgpt-go', 'اشتراك ChatGPT Go', 'ChatGPT Go Subscription', 'اشتراك اقتصادي — 10,000 دينار.', 'Budget plan — 10,000 IQD.', 'اشتراك ChatGPT Go بسعر أقل ومميزات أقل من Plus.\n\nيتم التفعيل بالتنسيق مع الدعم بعد تأكيد الدفع. لا نطلب كلمة المرور أو رمز التحقق أبداً.', 'ChatGPT Go: lower price, fewer features than Plus.\n\nActivation is arranged with support after payment is confirmed. We never ask for your password or verification code.', 'chat', NULL, 'package', NULL, NULL, 1, 3, 'من 10 دقائق إلى ساعة بعد تأكيد الدفع', '10 minutes to 1 hour after payment is confirmed', 1, 0, 0, 11, '2026-10-28 11:50:46.523', '2026-10-28 11:50:46.828');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (22, 3, 'gemini', 'اشتراك Gemini', 'Gemini Subscription', 'شهر بـ 5,000 أو سنة بـ 25,000 دينار.', '1 month 5,000 or 1 year 25,000 IQD.', 'اشتراك Gemini من Google.\n\nيتم التفعيل بالتنسيق مع الدعم بعد تأكيد الدفع. لا نطلب كلمة المرور أو رمز التحقق أبداً.', 'Google Gemini subscription.\n\nActivation is arranged with support after payment is confirmed. We never ask for your password or verification code.', 'spark', NULL, 'package', NULL, NULL, 1, 3, 'من 10 دقائق إلى ساعة بعد تأكيد الدفع', '10 minutes to 1 hour after payment is confirmed', 1, 0, 0, 12, '2026-10-28 11:50:46.523', '2026-10-28 11:50:46.828');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (23, 3, 'claude', 'اشتراك Claude (شهري)', 'Claude Subscription (monthly)', 'اشتراك شهري — 30,000 دينار.', 'Monthly — 30,000 IQD.', 'اشتراك Claude الشهري.\n\nيتم التفعيل بالتنسيق مع الدعم بعد تأكيد الدفع. لا نطلب كلمة المرور أو رمز التحقق أبداً.', 'Monthly Claude subscription.\n\nActivation is arranged with support after payment is confirmed. We never ask for your password or verification code.', 'spark', NULL, 'package', NULL, NULL, 1, 3, 'من 10 دقائق إلى ساعة بعد تأكيد الدفع', '10 minutes to 1 hour after payment is confirmed', 1, 0, 0, 13, '2026-10-28 11:50:46.523', '2026-10-28 11:50:46.828');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (24, 3, 'iphone-plus-yearly', 'اشتراك iPhone Plus (سنوي)', 'iPhone Plus Subscription (yearly)', 'سنة كاملة بـ 25,000 دينار.', 'A full year for 25,000 IQD.', 'اشتراك iPhone Plus لمدة سنة (لا يتوفر اشتراك شهري).\n\nيتم التفعيل بالتنسيق مع الدعم بعد تأكيد الدفع. لا نطلب كلمة المرور أو رمز التحقق أبداً.', 'iPhone Plus for one year (no monthly plan available).\n\nActivation is arranged with support after payment is confirmed. We never ask for your password or verification code.', 'phone', NULL, 'package', NULL, NULL, 1, 3, 'من 10 دقائق إلى ساعة بعد تأكيد الدفع', '10 minutes to 1 hour after payment is confirmed', 1, 0, 0, 14, '2026-10-28 11:50:46.523', '2026-10-28 11:50:46.828');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (25, 3, 'telegram-premium', 'تلكرام بريميوم (النجمة)', 'Telegram Premium', 'النجمة وأسماء مميزة — من 10,000 دينار للشهر.', 'Star badge and name styles — from 10,000 IQD a month.', 'تفعيل تلكرام بريميوم (النجمة، أنماط أسماء مختلفة وباقي المميزات) على حسابك مباشرة بمعرّفك فقط.\n\nيتم التفعيل بالتنسيق مع الدعم بعد تأكيد الدفع. لا نطلب كلمة المرور أو رمز التحقق أبداً.', 'Telegram Premium (star badge, name styles and all premium features) activated on your account using only your username.\n\nActivation is arranged with support after payment is confirmed. We never ask for your password or verification code.', 'chat', NULL, 'package', NULL, NULL, 1, 3, 'من 10 إلى 20 دقيقة بعد تأكيد الدفع', '10–20 minutes after payment is confirmed', 1, 1, 0, 20, '2026-10-28 11:50:46.523', '2026-10-28 11:50:46.827');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (26, 3, 'telegram-stars', 'نجوم تلكرام', 'Telegram Stars', '100 نجمة بـ 3,000 دينار — وكميات أكبر حسب الطلب.', '100 Stars for 3,000 IQD — larger amounts on request.', 'نجوم تلكرام ترسل لحسابك بمعرّفك فقط. للكميات الأكبر اطلب «خدمة خاصة».', 'Telegram Stars sent to your account using only your username. For larger amounts, send a custom request.', 'spark', NULL, 'package', NULL, NULL, 1, 5, 'من 10 إلى 20 دقيقة بعد تأكيد الدفع', '10–20 minutes after payment is confirmed', 1, 0, 0, 21, '2026-10-28 11:50:46.523', '2026-10-28 11:50:46.827');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (27, 4, 'procession-design', 'تصاميم المواكب والحسينيات', 'Procession & Husseiniya Designs', '5,000 دينار للتصميم الواحد حسب المتطلبات.', '5,000 IQD per design, depending on requirements.', 'تصاميم للمواكب والحسينيات والمناسبات الدينية: بوسترات، لافتات، وتصاميم سوشل ميديا. السعر للتصميم الواحد، والطلبات المعقدة يُتفق عليها مع الدعم.', 'Designs for processions, Husseiniyas and religious occasions: posters, banners and social media designs. Price is per design; complex requests are agreed with support.', 'image', NULL, 'unit', 5000, NULL, 1, 30, 'من 1 إلى 3 أيام', '1 to 3 days', 1, 0, 0, 5, '2026-10-28 11:50:46.523', '2026-10-28 11:50:46.523');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (28, 2, 'mobile-legends-diamonds', 'ألماس موبايل ليجندز', 'Mobile Legends Diamonds', 'شحن ألماس Mobile Legends: Bang Bang برقم اللاعب ورقم السيرفر فقط.', 'Mobile Legends: Bang Bang diamonds with your player ID and Zone ID only.', 'اختر الباقة واكتب رقم اللاعب (ID) ورقم السيرفر (Zone ID) — تلكاهم بالضغط على صورتك داخل اللعبة.\n\nلا نطلب كلمة المرور أبداً. الشحن على رقم خاطئ قد لا يمكن استرجاعه، فتأكد من الرقمين.', 'Choose a package and enter your player ID and Zone ID — tap your profile picture in the game to see them.\n\nWe never ask for your password. A top-up to a wrong ID may not be refundable, so check both numbers.', 'gem', NULL, 'package', NULL, NULL, 1, 10, 'من 10 إلى 20 دقيقة بعد تأكيد الدفع', '10–20 minutes after payment is confirmed', 1, 1, 0, 15, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.702');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (29, 14, 'playstation-gift-card', 'بطاقة بلايستيشن (PSN)', 'PlayStation Gift Card (PSN)', 'بطاقات $10 و$25 و$50 للحساب الأمريكي — الكود يوصلك بصفحة الطلب.', '$10, $25, $50 cards for US accounts — the code arrives on your order page.', 'اختر قيمة البطاقة وادفع، وبعد تأكيد التحويل نرسل لك الكود في صفحة طلبك.\n\n• البطاقة للحساب الأمريكي (US) — تشتغل فقط على حساب منطقته الولايات المتحدة.\n• الدفع أولاً، وبعد تأكيد التحويل يظهر الكود في صفحة طلبك (قسم «تفاصيل التسليم») خلال 10 إلى 20 دقيقة.\n• الأكواد الرقمية لا تُسترجع بعد تسليمها.', 'Choose the card value and pay; after the transfer is confirmed we send the code to your order page.\n\n• The card is for US accounts — it only works on an account whose region is the United States.\n• Payment first: once the transfer is confirmed, the code appears on your order page (“Delivery details”) within 10–20 minutes.\n• Digital codes cannot be refunded once delivered.', 'gamepad', NULL, 'package', NULL, NULL, 1, 5, 'من 10 إلى 20 دقيقة بعد تأكيد الدفع', '10–20 minutes after payment is confirmed', 1, 1, 0, 10, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.702');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (30, 14, 'steam-gift-card', 'بطاقة ستيم (Steam)', 'Steam Wallet Card', 'بطاقات $10 و$20 و$50 للحساب الأمريكي — الكود يوصلك بصفحة الطلب.', '$10, $20, $50 cards for US accounts — the code arrives on your order page.', 'اختر قيمة البطاقة وادفع، وبعد تأكيد التحويل نرسل لك الكود في صفحة طلبك.\n\n• البطاقة للحساب الأمريكي (US) — تشتغل فقط على حساب منطقته الولايات المتحدة.\n• الدفع أولاً، وبعد تأكيد التحويل يظهر الكود في صفحة طلبك (قسم «تفاصيل التسليم») خلال 10 إلى 20 دقيقة.\n• الأكواد الرقمية لا تُسترجع بعد تسليمها.', 'Choose the card value and pay; after the transfer is confirmed we send the code to your order page.\n\n• The card is for US accounts — it only works on an account whose region is the United States.\n• Payment first: once the transfer is confirmed, the code appears on your order page (“Delivery details”) within 10–20 minutes.\n• Digital codes cannot be refunded once delivered.', 'gamepad', NULL, 'package', NULL, NULL, 1, 5, 'من 10 إلى 20 دقيقة بعد تأكيد الدفع', '10–20 minutes after payment is confirmed', 1, 0, 0, 20, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.702');
