INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (34, 3, 'shahid-vip', 'اشتراك شاهد VIP', 'Shahid VIP', 'مسلسلات وأفلام وبرامج عربية حصرية بدون إعلانات.', 'Exclusive Arabic series, films and shows without ads.', 'اختر المدة وادفع.\n\nيتم التفعيل على حسابك أنت بكود أو دعوة رسمية بعد تأكيد الدفع، ونتواصل معك إذا احتجنا تفاصيل. لا نطلب كلمة المرور أو رمز التحقق أبداً.', 'Choose the duration and pay.\n\nActivation is on your own account with an official code or invite after payment is confirmed; we contact you if we need details. We never ask for your password or verification code.', 'tv', NULL, 'package', NULL, NULL, 1, 3, 'من 10 دقائق إلى ساعة بعد تأكيد الدفع', '10 minutes to 1 hour after payment is confirmed', 1, 0, 0, 60, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.702');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (35, 3, 'youtube-premium', 'اشتراك يوتيوب بريميوم', 'YouTube Premium', 'فردي 10,000 · عائلي 15,000 (حتى 5 أفراد) · طالب 5,000 دينار شهرياً.', 'Individual 10,000 · Family 15,000 (up to 5 members) · Student 5,000 IQD a month.', 'يوتيوب بدون إعلانات، تشغيل بالخلفية، وتنزيل الفيديوهات، ويشمل YouTube Music.\n\n• فردي: حساب واحد.\n• عائلي: تضيف حتى 5 أفراد من عائلتك، أعمارهم 13 سنة فما فوق، كل واحد بحسابه. اكتب إيميلاتهم بالخانة المخصصة.\n• طالب: حسب شروط يوتيوب لاشتراك الطلاب (قد يُطلب التحقق من أنك طالب).\n\nيتم التفعيل على حسابك أنت بكود أو دعوة رسمية بعد تأكيد الدفع، ونتواصل معك إذا احتجنا تفاصيل. لا نطلب كلمة المرور أو رمز التحقق أبداً.', 'YouTube without ads, background play and downloads, including YouTube Music.\n\n• Individual: one account.\n• Family: add up to 5 family members aged 13 or older, each with their own account. List their emails in the field provided.\n• Student: subject to YouTube\'s student-plan terms (student verification may be required).\n\nActivation is on your own account with an official code or invite after payment is confirmed; we contact you if we need details. We never ask for your password or verification code.', 'tv', NULL, 'package', NULL, NULL, 1, 3, 'من 10 دقائق إلى ساعة بعد تأكيد الدفع', '10 minutes to 1 hour after payment is confirmed', 1, 0, 0, 70, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.873');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (36, 3, 'spotify-premium', 'اشتراك سبوتيفاي بريميوم', 'Spotify Premium', 'موسيقى بدون إعلانات وتنزيل للاستماع بدون إنترنت.', 'Ad-free music and downloads for offline listening.', 'اختر المدة وادفع.\n\nيتم التفعيل على حسابك أنت بكود أو دعوة رسمية بعد تأكيد الدفع، ونتواصل معك إذا احتجنا تفاصيل. لا نطلب كلمة المرور أو رمز التحقق أبداً.', 'Choose the duration and pay.\n\nActivation is on your own account with an official code or invite after payment is confirmed; we contact you if we need details. We never ask for your password or verification code.', 'music', NULL, 'package', NULL, NULL, 1, 3, 'من 10 دقائق إلى ساعة بعد تأكيد الدفع', '10 minutes to 1 hour after payment is confirmed', 1, 0, 0, 80, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.702');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (37, 3, 'netflix', 'اشتراك نتفليكس', 'Netflix', 'أفلام ومسلسلات بجودة عالية على حسابك الخاص.', 'Films and series in high quality on your own account.', 'اختر المدة وادفع.\n\nيتم التفعيل على حسابك أنت بكود أو دعوة رسمية بعد تأكيد الدفع، ونتواصل معك إذا احتجنا تفاصيل. لا نطلب كلمة المرور أو رمز التحقق أبداً.', 'Choose the duration and pay.\n\nActivation is on your own account with an official code or invite after payment is confirmed; we contact you if we need details. We never ask for your password or verification code.', 'tv', NULL, 'package', NULL, NULL, 1, 3, 'من 10 دقائق إلى ساعة بعد تأكيد الدفع', '10 minutes to 1 hour after payment is confirmed', 1, 0, 0, 90, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.702');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (38, 3, 'canva-pro', 'اشتراك Canva (Pro و Business)', 'Canva subscription (Pro & Business)', 'Pro: 30,000 شهرياً أو 225,000 سنوياً · Business: 42,000 شهرياً أو 400,000 سنوياً.', 'Pro: 30,000 a month or 225,000 a year · Business: 42,000 a month or 400,000 a year.', 'كل قوالب وأدوات Canva المدفوعة للتصميم.\n\n• Pro: لشخص واحد.\n• Business: للفرق والشركات، مع أدوات الهوية التجارية والعمل الجماعي.\n\nيتم التفعيل على حسابك أنت بكود أو دعوة رسمية بعد تأكيد الدفع، ونتواصل معك إذا احتجنا تفاصيل. لا نطلب كلمة المرور أو رمز التحقق أبداً.', 'All of Canva\'s premium templates and tools.\n\n• Pro: for one person.\n• Business: for teams and companies, with brand and collaboration tools.\n\nActivation is on your own account with an official code or invite after payment is confirmed; we contact you if we need details. We never ask for your password or verification code.', 'palette', NULL, 'package', NULL, NULL, 1, 3, 'من 10 دقائق إلى ساعة بعد تأكيد الدفع', '10 minutes to 1 hour after payment is confirmed', 1, 0, 0, 100, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.877');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (39, 3, 'capcut-pro', 'اشتراك CapCut Pro', 'CapCut Pro', 'مونتاج احترافي بدون علامة مائية مع مؤثرات Pro.', 'Pro editing without watermark and with Pro effects.', 'اختر المدة وادفع.\n\nيتم التفعيل على حسابك أنت بكود أو دعوة رسمية بعد تأكيد الدفع، ونتواصل معك إذا احتجنا تفاصيل. لا نطلب كلمة المرور أو رمز التحقق أبداً.', 'Choose the duration and pay.\n\nActivation is on your own account with an official code or invite after payment is confirmed; we contact you if we need details. We never ask for your password or verification code.', 'tv', NULL, 'package', NULL, NULL, 1, 3, 'من 10 دقائق إلى ساعة بعد تأكيد الدفع', '10 minutes to 1 hour after payment is confirmed', 1, 0, 0, 110, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.702');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (40, 4, 'logo-design', 'تصميم شعار (لوگو)', 'Logo Design', 'شعار احترافي لمشروعك مع ملفات جاهزة للطباعة والسوشل.', 'A professional logo with files ready for print and social media.', '• أساسي: مقترحين وتعديلين.\n• احترافي: 3 مقترحات، تعديلات أكثر، وملفات المصدر.\n• هوية مصغّرة: شعار + كرت أعمال + غلاف سوشل ميديا.', '• Basic: 2 concepts and 2 revisions.\n• Pro: 3 concepts, more revisions and source files.\n• Mini identity: logo + business card + social media cover.', 'palette', NULL, 'package', NULL, NULL, 1, 3, 'من 2 إلى 5 أيام', '2 to 5 days', 1, 0, 0, 50, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.702');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (41, 4, 'menu-design', 'تصميم منيو مطعم أو كافيه', 'Restaurant / Café Menu Design', 'منيو مرتب وجذاب للطباعة أو للعرض على الشاشة والسوشل.', 'A clear, attractive menu for print, screens or social media.', 'اكتب أسماء الأصناف والأسعار، أو أرسل رابط ملف فيه القائمة، ونصمم المنيو بألوان مشروعك.', 'Write the items and prices, or send a link to a file with the list, and we design the menu in your brand colours.', 'palette', NULL, 'package', NULL, NULL, 1, 3, 'من 2 إلى 4 أيام', '2 to 4 days', 1, 0, 0, 60, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.702');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (42, 4, 'business-card-design', 'تصميم كرت أعمال (بزنس كارد)', 'Business Card Design', 'كرت أعمال بوجهين جاهز للطباعة.', 'A two-sided business card, print-ready.', 'اكتب الاسم والمسمّى وأرقام التواصل، ونسلّمك ملف جاهز للطباعة.', 'Send the name, title and contact details, and get a print-ready file.', 'palette', NULL, 'unit', 15000, NULL, 1, 10, 'من 1 إلى 3 أيام', '1 to 3 days', 1, 0, 0, 70, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.702');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (43, 4, 'invitation-design', 'تصميم دعوة (عرس أو مناسبة)', 'Invitation Design (wedding or event)', 'دعوة صورة أو فيديو متحرك لإرسالها على واتساب والسوشل.', 'An image or animated video invitation to share on WhatsApp and social media.', 'اكتب الأسماء والتاريخ والمكان وأي نص تحبه، واختر صورة أو فيديو متحرك.', 'Send the names, date, place and any wording you like, and choose an image or an animated video.', 'image', NULL, 'package', NULL, NULL, 1, 5, 'من 1 إلى 3 أيام', '1 to 3 days', 1, 0, 0, 80, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.702');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (44, 15, 'reels-montage', 'مونتاج ريلز وتيك توك', 'Reels & TikTok Editing', 'مونتاج سريع ومرتب حتى 60 ثانية مع نصوص وموسيقى وانتقالات.', 'Snappy edits up to 60 seconds with captions, music and transitions.', 'أرسل رابط الفيديوهات (مثل Google Drive) واكتب الفكرة والأسلوب. كل ريل حتى 60 ثانية مع تعديل واحد.', 'Send a link to your clips (e.g. Google Drive) and describe the idea and style. Each reel is up to 60 seconds with one revision.', 'tv', NULL, 'package', NULL, NULL, 1, 5, 'من 1 إلى 3 أيام', '1 to 3 days', 1, 1, 0, 10, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.702');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (45, 15, 'ad-video-montage', 'مونتاج فيديو إعلاني', 'Ad Video Editing', 'فيديو إعلاني لمشروعك مع نصوص وموسيقى وشعارك.', 'A promotional video for your business with captions, music and your logo.', 'أرسل المواد المتوفرة (فيديوهات، صور، شعار) واكتب الرسالة الإعلانية. يشمل تعديلين.', 'Send the material you have (clips, photos, logo) and your ad message. Includes two revisions.', 'megaphone', NULL, 'package', NULL, NULL, 1, 3, 'من 2 إلى 4 أيام', '2 to 4 days', 1, 0, 0, 20, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.702');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (46, 15, 'youtube-montage', 'مونتاج فيديو يوتيوب', 'YouTube Video Editing', 'قص وترتيب ونصوص وموسيقى لفيديوهات اليوتيوب.', 'Cutting, pacing, captions and music for YouTube videos.', 'أرسل رابط التسجيل الخام واكتب طريقة المونتاج المطلوبة. يشمل تعديل واحد.', 'Send a link to the raw footage and describe the editing you want. Includes one revision.', 'tv', NULL, 'package', NULL, NULL, 1, 5, 'من 2 إلى 5 أيام', '2 to 5 days', 1, 0, 0, 30, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.702');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (47, 16, 'manage-instagram', 'إدارة حساب إنستغرام', 'Instagram Account Management', 'باقات شهرية: أساسية، متقدمة، واحترافية — حسب نوع حسابك واحتياجك.', 'Monthly packages: basic, advanced and pro — by your account type and needs.', 'الباقات شهرية وتشمل:\n• أساسية: 12 منشور شهرياً + الرد على التعليقات\n• متقدمة: 20 منشور + 10 ستوري + 4 ريلز + الرد على الرسائل\n• احترافية: 30 منشور + 8 ريلز + ستوري يومي + إدارة إعلان + تقرير شهري\n\nبعد تأكيد الدفع نتواصل معك لنتفق على الخطة والمحتوى، ونُضاف كمسؤول أو شريك من الأدوات الرسمية (مثل Meta Business Suite) — لا نطلب كلمة المرور. ميزانية الإعلانات الممولة غير مشمولة وتدفعها للمنصة مباشرة. لا نضمن أعداد متابعين؛ نضمن عملاً منتظماً وتقريراً واضحاً.', 'Monthly packages include:\n• Basic: 12 posts a month + replying to comments\n• Advanced: 20 posts + 10 stories + 4 reels + replying to messages\n• Pro: 30 posts + 8 reels + daily stories + ad management + monthly report\n\nAfter payment we contact you to agree on the plan and content, and we are added as a manager or partner with official tools (such as Meta Business Suite) — no password. Ad spend is not included; you pay it to the platform directly. We do not guarantee follower numbers; we guarantee consistent work and a clear report.', 'briefcase', NULL, 'package', NULL, NULL, 1, 3, 'نتواصل معك خلال 24 ساعة من تأكيد الدفع', 'We contact you within 24 hours of payment', 1, 0, 0, 10, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.702');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (48, 16, 'manage-tiktok', 'إدارة حساب تيك توك', 'TikTok Account Management', 'باقات شهرية: أساسية، متقدمة، واحترافية — حسب نوع حسابك واحتياجك.', 'Monthly packages: basic, advanced and pro — by your account type and needs.', 'الباقات شهرية وتشمل:\n• أساسية: 8 فيديوهات شهرياً + اختيار الترندات\n• متقدمة: 15 فيديو + كتابة الأفكار + الرد على التعليقات\n• احترافية: 30 فيديو + خطة محتوى + إدارة إعلان + تقرير شهري\n\nبعد تأكيد الدفع نتواصل معك لنتفق على الخطة والمحتوى، ونُضاف كمسؤول أو شريك من الأدوات الرسمية (مثل Meta Business Suite) — لا نطلب كلمة المرور. ميزانية الإعلانات الممولة غير مشمولة وتدفعها للمنصة مباشرة. لا نضمن أعداد متابعين؛ نضمن عملاً منتظماً وتقريراً واضحاً.', 'Monthly packages include:\n• Basic: 8 videos a month + trend selection\n• Advanced: 15 videos + idea writing + replying to comments\n• Pro: 30 videos + content plan + ad management + monthly report\n\nAfter payment we contact you to agree on the plan and content, and we are added as a manager or partner with official tools (such as Meta Business Suite) — no password. Ad spend is not included; you pay it to the platform directly. We do not guarantee follower numbers; we guarantee consistent work and a clear report.', 'briefcase', NULL, 'package', NULL, NULL, 1, 3, 'نتواصل معك خلال 24 ساعة من تأكيد الدفع', 'We contact you within 24 hours of payment', 1, 0, 0, 20, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.702');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (49, 16, 'manage-facebook', 'إدارة صفحة فيسبوك', 'Facebook Page Management', 'باقات شهرية: أساسية، متقدمة، واحترافية — حسب نوع حسابك واحتياجك.', 'Monthly packages: basic, advanced and pro — by your account type and needs.', 'الباقات شهرية وتشمل:\n• أساسية: 12 منشور شهرياً + الرد على التعليقات\n• متقدمة: 20 منشور + الرد على الرسائل + تحسين الصفحة\n• احترافية: 30 منشور + إدارة إعلان + تقرير شهري\n\nبعد تأكيد الدفع نتواصل معك لنتفق على الخطة والمحتوى، ونُضاف كمسؤول أو شريك من الأدوات الرسمية (مثل Meta Business Suite) — لا نطلب كلمة المرور. ميزانية الإعلانات الممولة غير مشمولة وتدفعها للمنصة مباشرة. لا نضمن أعداد متابعين؛ نضمن عملاً منتظماً وتقريراً واضحاً.', 'Monthly packages include:\n• Basic: 12 posts a month + replying to comments\n• Advanced: 20 posts + replying to messages + page optimisation\n• Pro: 30 posts + ad management + monthly report\n\nAfter payment we contact you to agree on the plan and content, and we are added as a manager or partner with official tools (such as Meta Business Suite) — no password. Ad spend is not included; you pay it to the platform directly. We do not guarantee follower numbers; we guarantee consistent work and a clear report.', 'briefcase', NULL, 'package', NULL, NULL, 1, 3, 'نتواصل معك خلال 24 ساعة من تأكيد الدفع', 'We contact you within 24 hours of payment', 1, 0, 0, 30, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.702');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (50, 16, 'manage-all-platforms', 'إدارة متكاملة لكل المنصات', 'All-Platform Management', 'باقات شهرية: أساسية، متقدمة، واحترافية — حسب نوع حسابك واحتياجك.', 'Monthly packages: basic, advanced and pro — by your account type and needs.', 'الباقات شهرية وتشمل:\n• أساسية: إنستغرام + فيسبوك: 12 منشور مشترك + الردود\n• متقدمة: إنستغرام + فيسبوك + تيك توك: 20 منشور + 8 فيديو + الردود\n• احترافية: كل المنصات: محتوى يومي + ريلز + إدارة إعلانات + تقرير شهري\n\nبعد تأكيد الدفع نتواصل معك لنتفق على الخطة والمحتوى، ونُضاف كمسؤول أو شريك من الأدوات الرسمية (مثل Meta Business Suite) — لا نطلب كلمة المرور. ميزانية الإعلانات الممولة غير مشمولة وتدفعها للمنصة مباشرة. لا نضمن أعداد متابعين؛ نضمن عملاً منتظماً وتقريراً واضحاً.', 'Monthly packages include:\n• Basic: Instagram + Facebook: 12 shared posts + replies\n• Advanced: Instagram + Facebook + TikTok: 20 posts + 8 videos + replies\n• Pro: All platforms: daily content + reels + ad management + monthly report\n\nAfter payment we contact you to agree on the plan and content, and we are added as a manager or partner with official tools (such as Meta Business Suite) — no password. Ad spend is not included; you pay it to the platform directly. We do not guarantee follower numbers; we guarantee consistent work and a clear report.', 'briefcase', NULL, 'package', NULL, NULL, 1, 3, 'نتواصل معك خلال 24 ساعة من تأكيد الدفع', 'We contact you within 24 hours of payment', 1, 0, 0, 40, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.702');
INSERT INTO `products` (`id`, `category_id`, `slug`, `name_ar`, `name_en`, `summary_ar`, `summary_en`, `description_ar`, `description_en`, `icon`, `image_file_id`, `pricing_mode`, `unit_price`, `compare_at_price`, `min_quantity`, `max_quantity`, `delivery_time_ar`, `delivery_time_en`, `is_active`, `is_featured`, `is_sample`, `sort_order`, `created_at`, `updated_at`) VALUES (51, 16, 'manage-ad-campaigns', 'إدارة الحملات الإعلانية الممولة', 'Paid Ad Campaign Management', 'إعداد ومتابعة إعلاناتك على إنستغرام وفيسبوك وتيك توك — رسوم الإدارة فقط.', 'Setting up and managing your Instagram, Facebook and TikTok ads — management fee only.', 'نختار الجمهور ونكتب الإعلان ونتابع النتائج ونحسّنها. ميزانية الإعلان غير مشمولة وتدفعها أنت للمنصة مباشرة من حسابك. نُضاف كشريك إعلاني — لا نطلب كلمة المرور.', 'We choose the audience, write the ad, track the results and improve them. Ad spend is not included; you pay it to the platform from your own account. We are added as an ad partner — no password.', 'megaphone', NULL, 'package', NULL, NULL, 1, 3, 'نتواصل معك خلال 24 ساعة من تأكيد الدفع', 'We contact you within 24 hours of payment', 1, 0, 0, 50, '2026-10-28 11:50:46.702', '2026-10-28 11:50:46.702');
